mapper.insert:
INSERT INTO ifj_trigger_work_item (
    trigger_id, status, available_at, expires_at, attempt_count, max_attempts
) VALUES (
    #{triggerId}, 'READY', CURRENT_TIMESTAMP(3), #{expiresAt,jdbcType=TIMESTAMP}, 0, #{maxAttempts}
)
ON DUPLICATE KEY UPDATE trigger_id = VALUES(trigger_id)

mapper.select:
SELECT * FROM (
SELECT work_item.trigger_id FROM ifj_trigger_work_item work_item JOIN ifj_instance root_instance ON root_instance.id = work_item.root_instance_id AND root_instance.parent_instance_id IS NULL WHERE root_instance.status IN ('WAITING', 'RUNNING', 'PAUSED', 'WAITING_EVENT') AND root_instance.timeout_at IS NOT NULL AND root_instance.timeout_at <= CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3)) AND ( work_item.status IN ('READY', 'RETRY_WAIT', 'SUSPENDED', 'DEAD') OR (work_item.status = 'CLAIMED' AND work_item.lease_deadline <= CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3))) ) ORDER BY root_instance.timeout_at ASC, work_item.trigger_id ASC
) WHERE ROWNUM <= #{limit}

