UPDATE ifj_trigger_work_item
SET root_instance_id = #{rootInstanceId},
    update_time = CURRENT_TIMESTAMP(3)
WHERE trigger_id = #{triggerId}
  AND status = 'CLAIMED'
  AND lease_owner = #{leaseOwner}
  AND claim_token = #{claimToken}
  AND fence_token = #{fenceToken}
  AND lease_deadline > CURRENT_TIMESTAMP(3)
  AND (root_instance_id IS NULL OR root_instance_id = #{rootInstanceId})

UPDATE ifj_trigger_work_item
