mapper.insert:
INSERT INTO ifj_trigger_work_item (
    trigger_id, status, available_at, expires_at, attempt_count, max_attempts
) VALUES (
    #{triggerId}, 'READY', CURRENT_TIMESTAMP(3), #{expiresAt,jdbcType=TIMESTAMP}, 0, #{maxAttempts}
)
ON CONFLICT (trigger_id) DO NOTHING

INSERT INTO ifj_trigger_work_item (
    trigger_id, status, available_at, expires_at, attempt_count, max_attempts
) VALUES (
    #{triggerId}, 'READY', strftime('%Y-%m-%d %H:%M:%f','now'), #{expiresAt,jdbcType=TIMESTAMP}, 0, #{maxAttempts}
)
ON CONFLICT (trigger_id) DO NOTHING

MERGE INTO ifj_trigger_work_item target
USING (SELECT 1 AS marker FROM dual) source
ON (target.trigger_id = #{triggerId})
WHEN NOT MATCHED THEN INSERT (
    trigger_id, status, available_at, expires_at, attempt_count, max_attempts
) VALUES (
    #{triggerId}, 'READY', CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3)), #{expiresAt,jdbcType=TIMESTAMP}, 0, #{maxAttempts}
)

        IF NOT EXISTS (SELECT 1 FROM ifj_trigger_work_item WITH (UPDLOCK, HOLDLOCK) WHERE trigger_id = #{triggerId})
        BEGIN

        INSERT INTO ifj_trigger_work_item (
            trigger_id, status, available_at, expires_at, attempt_count, max_attempts
        ) VALUES (
            #{triggerId}, 'READY', SYSUTCDATETIME(), #{expiresAt,jdbcType=TIMESTAMP}, 0, #{maxAttempts}
        )
        END

mapper.select:
SELECT * FROM (
SELECT work_item.trigger_id FROM ifj_trigger_work_item work_item JOIN ifj_instance root_instance ON root_instance.id = work_item.root_instance_id AND root_instance.parent_instance_id IS NULL WHERE work_item.status = 'DEAD' AND work_item.update_time <= CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3)) - NUMTODSINTERVAL(#{orphanGraceMicros} / 1000000, 'SECOND') AND root_instance.status IN ('WAITING', 'RUNNING', 'PAUSED', 'WAITING_EVENT') ORDER BY work_item.update_time ASC, work_item.trigger_id ASC
) WHERE ROWNUM <= #{limit}

mapper.update:
UPDATE ifj_trigger_work_item
SET lease_deadline = (CURRENT_TIMESTAMP(3) + (#{leaseMicros} * INTERVAL '1 microsecond')),
    update_time = CURRENT_TIMESTAMP(3)
WHERE trigger_id = #{triggerId}
  AND status = 'CLAIMED'
  AND lease_owner = #{leaseOwner}
  AND claim_token = #{claimToken}
  AND fence_token = #{fenceToken}
  AND lease_deadline > CURRENT_TIMESTAMP(3)

UPDATE ifj_trigger_work_item
SET lease_deadline = strftime('%Y-%m-%d %H:%M:%f','now', printf('+%.6f seconds', (#{leaseMicros} / 1000000.0))),
    update_time = strftime('%Y-%m-%d %H:%M:%f','now')
WHERE trigger_id = #{triggerId}
  AND status = 'CLAIMED'
  AND lease_owner = #{leaseOwner}
  AND claim_token = #{claimToken}
  AND fence_token = #{fenceToken}
  AND lease_deadline > strftime('%Y-%m-%d %H:%M:%f','now')

UPDATE ifj_trigger_work_item
SET lease_deadline = CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3)) + NUMTODSINTERVAL(#{leaseMicros} / 1000000, 'SECOND'),
    update_time = CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3))
WHERE trigger_id = #{triggerId}
  AND status = 'CLAIMED'
  AND lease_owner = #{leaseOwner}
  AND claim_token = #{claimToken}
  AND fence_token = #{fenceToken}
  AND lease_deadline > CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3))

UPDATE ifj_trigger_work_item
SET lease_deadline = DATEADD(MILLISECOND, (#{leaseMicros} / 1000), SYSUTCDATETIME()),
    update_time = SYSUTCDATETIME()
WHERE trigger_id = #{triggerId}
  AND status = 'CLAIMED'
  AND lease_owner = #{leaseOwner}
  AND claim_token = #{claimToken}
  AND fence_token = #{fenceToken}
  AND lease_deadline > SYSUTCDATETIME()
